import{_ as t,c as a,o,ae as i}from"./chunks/framework.Bi6zybwU.js";const c=JSON.parse('{"title":"Featured Image","description":"Featured Image","frontmatter":{"title":"Featured Image","description":"Featured Image"},"headers":[],"relativePath":"guide/wordpress-integration/featured-image.md","filePath":"guide/wordpress-integration/featured-image.md"}'),n={name:"guide/wordpress-integration/featured-image.md"};function s(r,e,l,d,p,u){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="featured-image" tabindex="-1">Featured Image <a class="header-anchor" href="#featured-image" aria-label="Permalink to &quot;Featured Image&quot;">​</a></h1><p>In Ninja Tables WP Posts table, you will find an option called <strong>Featured Image</strong> included in the **ACF **feature. To use this feature, create a table with the help of the **WP Post **option. Let&#39;s have a look at the table below, which is created using <a href="https://ninjatables.com/docs/create-wp-posts-table/" target="_blank" rel="noreferrer">WP Post</a>.</p><ul><li>To use the **Featured Image <strong>option</strong>, **click on the <strong>Add New Column</strong> tab located beside the <strong>Query Settings</strong> tab. After the Add New Column is clicked, an extended drop-down will appear with a set of options.</li><li>Go to the extended popup to get this feature, here you can find a section called <strong>Dynamic Post Data Settings</strong>. There’ll be two options for the segment, one being <strong>Field Type</strong> &amp; the other being <strong>Field Value</strong>.</li><li>Select the option Field Type, then the drop-down will appear. If you want to edit any featured image of your post table, just click on the** Featured Image** option. <img src="https://ninjatables.com/wp-content/uploads/2023/01/featured-image-3-1024x508.png" alt="Dynamic Post Data Settings"></li><li>Next, select the **Field Value **option from the dropdown. The image can be used as a thumbnail, medium, large, etc. You can select your preferred featured image size from here. <img src="https://ninjatables.com/wp-content/uploads/2023/01/featured-image-4-1024x487.png" alt="Field Value"></li><li>By checking the box you can connect the image to the post permalink and also check the Open Link To New tab to open the link to a new window. <img src="https://ninjatables.com/wp-content/uploads/2023/01/featured-image-5-1024x243.png" alt="Link to post Permalink"></li><li>A column of the featured images will then appear with the featured images on your table. Here’s an example – my post doesn’t hold any pictures so it doesn’t display anything in the image field. <img src="https://ninjatables.com/wp-content/uploads/2023/01/featured-image-6.webp" alt="Example"></li><li>Adding the feature image to a post will automatically be shown on your table’s image field. If a picture is attached to one of the posts, you can see this is included in the table you created. <img src="https://ninjatables.com/wp-content/uploads/2023/01/featured-image-7.webp" alt="post featured image"></li><li>So, look at the table’s final output after the image is included in your relative post. <img src="https://ninjatables.com/wp-content/uploads/2023/01/featured-image-8.webp" alt="post featured image in posts table"> This is how you can use the <strong>Featured</strong> <strong>image</strong> in** WP Post** table.</li></ul>',3)])])}const m=t(n,[["render",s]]);export{c as __pageData,m as default};
